# Complete URL Shortener System Test

Write-Host "`n" + ("=" * 80) -ForegroundColor Green
Write-Host "URL SHORTENER - COMPLETE SYSTEM TEST" -ForegroundColor Green
Write-Host ("=" * 80) -ForegroundColor Green

$script:testsPassed = 0
$script:testsFailed = 0

function Test-Step {
    param(
        [string]$Name,
        [scriptblock]$Action
    )

    Write-Host "`n[TEST] $Name" -ForegroundColor Cyan
    try {
        & $Action
        $script:testsPassed++
        Write-Host "✅ PASSED" -ForegroundColor Green
        return $true
    } catch {
        $script:testsFailed++
        Write-Host "❌ FAILED: $($_.Exception.Message)" -ForegroundColor Red
        return $false
    }
}

# TEST 1: Docker Services
Test-Step "Check All Docker Containers Running" {
    $containers = docker ps --format "{{.Names}}" | Where-Object { $_ -like "*url-shortner*" -or $_ -in @('postgres-primary', 'postgres-replica', 'redis', 'rabbitmq') }
    Write-Host "   Running containers: $($containers.Count)" -ForegroundColor White
    if ($containers.Count -lt 8) {
        throw "Expected 8+ containers, found $($containers.Count)"
    }
}

# TEST 2: Write Service Health
Test-Step "Write Service Health Check (Port 5001)" {
    $health = Invoke-RestMethod -Uri "http://localhost:5001/health" -TimeoutSec 5
    Write-Host "   Status: $($health.status)" -ForegroundColor White
    Write-Host "   Database: $($health.checks.database)" -ForegroundColor White
    Write-Host "   Redis: $($health.checks.redis)" -ForegroundColor White

    if ($health.status -ne "healthy") {
        throw "Write service unhealthy"
    }
}

# TEST 3: Redirect Service Health
Test-Step "Redirect Service Health Check (Port 5002)" {
