    }
}

# TEST 4: Create Short URL #1
$global:shortCode1 = $null
Test-Step "Create Short URL (Google)" {
    $body = @{
        url = "https://www.google.com"
        created_by = "test-user"
    } | ConvertTo-Json

    $response = Invoke-RestMethod -Uri "http://localhost:5001/shorten" -Method POST -ContentType "application/json" -Body $body -TimeoutSec 5
    $global:shortCode1 = $response.short_url.Split('/')[-1]

    Write-Host "   Short Code: $global:shortCode1" -ForegroundColor Yellow
    Write-Host "   Short URL: $($response.short_url)" -ForegroundColor White
    Write-Host "   Original: $($response.original_url)" -ForegroundColor White

    if (!$global:shortCode1) {
        throw "No short code returned"
    }
}

