# TEST 6: Test Redirect #1
Test-Step "Test Redirect (Google)" {
    try {
        Invoke-WebRequest -Uri "http://localhost:5002/$global:shortCode1" -MaximumRedirection 0 -UseBasicParsing -TimeoutSec 5
        throw "Should have thrown redirect exception"
    } catch {
        if ($_.Exception.Response) {
            $statusCode = [int]$_.Exception.Response.StatusCode
            $location = $_.Exception.Response.Headers['Location']

            Write-Host "   Status: $statusCode" -ForegroundColor Yellow
            Write-Host "   Location: $location" -ForegroundColor White

            if ($statusCode -ne 301 -and $statusCode -ne 302) {
                throw "Expected 301/302, got $statusCode"
            }
            if ($location -ne "https://www.google.com") {
                throw "Wrong redirect location: $location"
            }
        } else {
            throw "Connection failed"
        }
    }
}

