# TEST 11: Load Test - Multiple Clicks
Test-Step "Load Test - 10 Rapid Clicks" {
    $clickCount = 0
    for ($i = 1; $i -le 10; $i++) {
        try {
            Invoke-WebRequest -Uri "http://localhost:5002/$global:shortCode1" -MaximumRedirection 0 -UseBasicParsing -TimeoutSec 2 -ErrorAction SilentlyContinue
        } catch {
            if ($_.Exception.Response -and ([int]$_.Exception.Response.StatusCode -eq 301 -or [int]$_.Exception.Response.StatusCode -eq 302)) {
                $clickCount++
            }
        }
        Start-Sleep -Milliseconds 100
    }

    Write-Host "   Successful redirects: $clickCount/10" -ForegroundColor Yellow

    if ($clickCount -lt 8) {
        throw "Too many failed redirects: $clickCount/10"
    }
}

