}

# TEST 13: Database Verification
Test-Step "Database - Verify URLs Exist" {
    $result = docker exec postgres-primary psql -U postgres -d urlshortener -t -c "SELECT COUNT(*) FROM urls WHERE short_code IN ('$global:shortCode1', '$global:shortCode2');"
    $count = [int]($result.Trim())

    Write-Host "   URLs in database: $count" -ForegroundColor Yellow

    if ($count -lt 2) {
        throw "Expected 2 URLs in database, found $count"
    }
}

# TEST 14: Database - Verify Click Events
Test-Step "Database - Verify Click Events Logged" {
    $result = docker exec postgres-primary psql -U postgres -d urlshortener -t -c "SELECT COUNT(*) FROM click_events WHERE short_code = '$global:shortCode1';"
    $count = [int]($result.Trim())

    Write-Host "   Click events: $count" -ForegroundColor Yellow

    if ($count -lt 5) {
        throw "Expected at least 5 click events, found $count"
    }
}

# TEST 15: Redis Cache Check
Test-Step "Redis - Verify URL Cached" {
    $cached = docker exec redis redis-cli GET "url:$global:shortCode1"

    Write-Host "   Cached URL: $cached" -ForegroundColor Yellow

    if (!$cached -or $cached -eq "(nil)") {
        throw "URL not cached in Redis"
    }
}

# TEST 16: RabbitMQ Queue Status
Test-Step "RabbitMQ - Verify Queue Processing" {
    $queueInfo = docker exec rabbitmq rabbitmqctl list_queues name messages consumers 2>$null | Select-String "url_clicks"

    if ($queueInfo) {
        Write-Host "   Queue info: $queueInfo" -ForegroundColor Yellow

        # Extract message count
        if ($queueInfo -match "url_clicks\s+(\d+)\s+(\d+)") {
            $messages = [int]$matches[1]
            $consumers = [int]$matches[2]

            Write-Host "   Pending messages: $messages" -ForegroundColor White
            Write-Host "   Active consumers: $consumers" -ForegroundColor White

            if ($consumers -lt 2) {
                throw "Expected 2 consumers, found $consumers"
            }
        }
    } else {
        throw "Queue not found"
    }
}

