    Write-Host "   Worker 1: $worker1" -ForegroundColor White
    Write-Host "   Worker 2: $worker2" -ForegroundColor White

    if ($worker1 -notlike "Up*" -or $worker2 -notlike "Up*") {
        throw "One or more workers not running"
    }
}

